// Business Charts > Maps: JSON > Editor Mode: Code.
// Coordenadas do centro de Boston, não do prédio do datacenter Boston 2.
const destination = { name: 'VPS · Boston 2', coords: [-71.0589, 42.3601] };
const read = (values, i) => typeof values?.get === 'function' ? values.get(i) : values?.[i];
const numeric = value => value === null || value === undefined || value === '' ? NaN : Number(value);
const grouped = new Map();
let receivedRows = 0;

function collect(lat, lon, count, country, city) {
  lat = numeric(lat); lon = numeric(lon); count = numeric(count);
  if (!Number.isFinite(lat) || !Number.isFinite(lon) || !Number.isFinite(count) ||
      Math.abs(lat) > 90 || Math.abs(lon) > 180 || count <= 0) return;
  const key = `${lat}|${lon}|${country || ''}|${city || ''}`;
  const previous = grouped.get(key);
  if (previous) { previous.count += count; return; }
  grouped.set(key, { lat, lon, count, country: String(country || ''), city: String(city || '') });
}

for (const frame of context.panel.data.series) {
  const fields = frame.fields || [];
  const find = (...names) => fields.find(f => names.includes(f.name));
  const lat = find('latitude', 'geoip_location_latitude');
  const lon = find('longitude', 'geoip_location_longitude');
  const country = find('País', 'geoip_country_name');
  const city = find('Cidade', 'geoip_city_name');
  const count = find('Acessos', 'Value', 'Value #A') ||
    fields.find(f => /^Value(?:\s.*)?$/.test(f.name)) ||
    fields.find(f => f.type === 'number' && f !== lat && f !== lon);
  receivedRows += frame.length ?? Math.max(0, ...fields.map(f => f.values?.length || 0));
  if (lat && lon && count) {
    for (let i = 0; i < count.values.length; i++) {
      collect(read(lat.values, i), read(lon.values, i), read(count.values, i),
        read(country?.values, i), read(city?.values, i));
    }
  } else {
    // Também aceita o formato de séries: coordenadas nos labels do valor.
    for (const f of fields.filter(f => f.type === 'number')) {
      const labels = f.labels || {};
      collect(labels.geoip_location_latitude, labels.geoip_location_longitude,
        read(f.values, f.values.length - 1), labels.geoip_country_name, labels.geoip_city_name);
    }
  }
}

const origins = [...grouped.values()].sort((a, b) => b.count - a.count).slice(0, 80);
const maximum = Math.max(1, ...origins.map(o => o.count));
const intensity = n => Math.log1p(n) / Math.log1p(maximum);
const color = n => intensity(n) > 0.8 ? '#B993FF' : intensity(n) > 0.45 ? '#39D7EF' : '#488DDE';
const format = n => Number(n).toLocaleString('pt-BR');
const total = origins.reduce((sum, o) => sum + o.count, 0);
const lines = origins.map(o => ({
  name: [o.city, o.country].filter(Boolean).join(' · ') || 'Origem geolocalizada',
  coords: [[o.lon, o.lat], destination.coords], value: o.count,
  lineStyle: { type: 'solid', color: color(o.count), width: 0.4 + 0.5 * intensity(o.count), opacity: 0.08 + 0.10 * intensity(o.count) }
}));
const points = origins.map(o => ({
  name: [o.city, o.country].filter(Boolean).join(' · ') || 'Origem geolocalizada',
  value: [o.lon, o.lat, o.count], itemStyle: { color: color(o.count) }
}));

return {
  backgroundColor: '#080F1D', animation: true, animationDurationUpdate: 800,
  tooltip: {
    trigger: 'item', renderMode: 'richText', backgroundColor: '#111E32',
    borderColor: '#304765', textStyle: { color: '#E7F1FF', fontSize: 12 },
    formatter: params => {
      if (params.seriesId === 'destination') {
        return `${destination.name}\nBoston, Massachusetts · posição aproximada\n${format(total)} acessos nas origens exibidas`;
      }
      const d = params.data;
      if (!d) return '';
      const n = Array.isArray(d.value) ? d.value[2] : d.value;
      return `${d.name}\n→ Boston 2\n${format(n)} acessos no período`;
    }
  },
  geo: {
    map: 'world', roam: true, zoom: 1.05, center: [-20, 18],
    top: '5%', bottom: '5%', left: '3%', right: '3%',
    scaleLimit: { min: 1, max: 12 },
    label: { show: false },
    itemStyle: { areaColor: '#13233B', borderColor: '#36506C', borderWidth: 0.55 },
    emphasis: { label: { show: false }, itemStyle: { areaColor: '#1D3553' } },
    select: { disabled: true }
  },
  graphic: origins.length ? [] : [{
    type: 'text', left: 'center', top: '85%', silent: true,
    style: { text: receivedRows ? 'Dados recebidos sem coordenadas ou contagem válidas' :
      'Consulta sem resultados neste intervalo', fill: '#93A7C4', fontSize: 14 }
  }],
  series: [
    {
      id: 'routes', name: 'Acessos', type: 'lines', coordinateSystem: 'geo', zlevel: 1,
      polyline: false, data: lines,
      lineStyle: { type: 'solid', curveness: 0.22 },
      effect: { show: true, period: 5, trailLength: 0.12, symbol: 'circle', symbolSize: 4, color: '#E0FCFF' },
      emphasis: { lineStyle: { type: 'solid', width: 1.2, opacity: 0.45 } }
    },
    {
      id: 'origins', name: 'Origens', type: 'effectScatter', coordinateSystem: 'geo', zlevel: 2,
      data: points, symbolSize: value => 4 + 8 * intensity(value[2]),
      rippleEffect: { period: 5, scale: 2.1, brushType: 'stroke' },
      showEffectOn: 'emphasis', label: { show: false },
      emphasis: { label: { show: false }, scale: 1.5 }
    },
    {
      id: 'destination', name: 'Boston 2', type: 'effectScatter', coordinateSystem: 'geo', zlevel: 3,
      data: [{ name: destination.name, value: [...destination.coords, total] }],
      symbol: 'circle', symbolSize: 15, showEffectOn: 'render',
      rippleEffect: { period: 3, scale: 4, brushType: 'stroke' },
      itemStyle: { color: '#F4C768', shadowBlur: 20, shadowColor: '#F4C768' },
      label: { show: true, formatter: 'BOSTON 2', position: 'right', distance: 12,
        color: '#FCE1A4', fontWeight: 700, fontSize: 12,
        backgroundColor: '#0B1628', padding: [6, 9], borderRadius: 4 }
    }
  ]
};

